int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long s, x;
    if (!(cin >> s >> x)) return 0;

    long long d = s - x;
    if (d < 0 || (d & 1)) {
        cout << 0;
        return 0;
    }

    long long c = d >> 1; // carry mask
    // Check that a & b = c is possible: (c & x) must be 0
    if (c & x) {
        cout << 0;
        return 0;
    }

    // Count number of bits set in x
    long long cnt = 0;
    for (int i = 0; i < 60; ++i) {
        if (x & (1LL << i)) cnt++;
    }

    // Number of (a,b) pairs with non-negative integers
    long long ans = (1LL << cnt);

    // Exclude the (0,0) pair if it exists (when c == 0)
    if (c == 0) ans -= 2; // (0,0) counted once, but (a,b) must be positive, so both (0,0) and (0,0) invalid -> subtract 2

    cout << (ans < 0 ? 0 : ans);
    return 0;
}

