int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long s, x;
    if (!(cin >> s >> x)) return 0;

    long long d = s - x;
    if (d < 0 || (d & 1)) {
        cout << 0;
        return 0;
    }

    long long a = d / 2;
    // Check that a & x == 0 (no overlapping bits)
    if ((a & x) != 0) {
        cout << 0;
        return 0;
    }

    // Count number of bits set in x
    int bits = __builtin_popcountll(x);
    // Total combinations for (a,b) with non-negative integers
    long long ans = 1LL << bits;

    // Exclude the case where b = 0 or a = 0 (since a,b must be positive)
    // That happens when a == 0 and b == x, or a == x and b == 0.
    // Both correspond to the same underlying (a,b) construction where a = 0.
    // This occurs only if a == 0.
    if (a == 0) ans -= 2;

    cout << (ans < 0 ? 0 : ans);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long s, x;
    if (!(cin >> s >> x)) return 0;

    // a + b = s, a ^ b = x
    // Let a & b = c, then:
    // s = (a ^ b) + 2 * (a & b) => s = x + 2c
    long long diff = s - x;
    if (diff < 0 || diff % 2 != 0) {
        cout << 0;
        return 0;
    }

    long long c = diff / 2;

    // c and x must not share any bit: (a & b) & (a ^ b) = 0
    if ((c & x) != 0) {
        cout << 0;
        return 0;
    }

    // Count number of bits set in x
    int bits = __builtin_popcountll(x);
    // Each set bit in x can be assigned to either a or b -> 2^bits possibilities
    long long ans = 1LL << bits;

    // Exclude the case where a or b is zero (since they must be positive)
    // This happens when a = c, b = c + x or vice versa, and one of them is 0.
    // That requires c = 0, so s = x.
    if (s == x) {
        // Two invalid cases: (0, x) and (x, 0)
        ans -= 2;
    }

    cout << ans;
    return 0;
}

